export type ActivityEventType =
  | 'booking_confirmed'
  | 'booking_cancelled'
  | 'new_client'
  | 'no_show'
  | 'payment_received'
  | 'rescheduled'
  | 'consent_signed'
  | 'artist_added'

interface ActivityLogRow {
  id: string
  studio_id: string
  event_type: string | null
  title: string | null
  detail: string | null
  created_at: string
}

export interface ActivityEvent {
  id: string
  type: ActivityEventType
  title: string
  detail: string
  timeAgo: string
}

const EVENT_ICONS: Record<ActivityEventType, LucideIcon> = {
  booking_confirmed: CalendarCheck2,
  booking_cancelled: CalendarX,
  new_client: UserPlus,
  no_show: UserX,
  payment_received: Banknote,
  rescheduled: CalendarArrowUp,
  consent_signed: FileCheck,
  artist_added: UserRoundPlus,
}

const EVENT_ICON_BG: Record<ActivityEventType, string> = {
  booking_confirmed: 'bg-primary/10 text-primary',
  booking_cancelled: 'bg-destructive/10 text-destructive',
  new_client: 'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)]',
  no_show: 'bg-[var(--color-warning-bg)] text-[var(--color-warning-foreground)]',
  payment_received: 'bg-cyan-500/10 text-cyan-600 dark:text-cyan-400',
  rescheduled: 'bg-[var(--color-warning-bg)] text-[var(--color-warning-foreground)]',
  consent_signed: 'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)]',
  artist_added: 'bg-secondary text-secondary-foreground',
}

function mapRowToEvent(raw: ActivityLogRow): ActivityEvent {
  return {
    id: raw.id,
    type: (raw.event_type ?? 'booking_confirmed') as ActivityEventType,
    title: raw.title ?? '',
    detail: raw.detail ?? '',
    timeAgo: raw.created_at
      ? formatTimeAgo(new Date(raw.created_at))
      : '',
  }
}

function formatTimeAgo(date: Date): string {
  const diffMs = Date.now() - date.getTime()
  const diffMin = Math.floor(diffMs / 60_000)
  if (diffMin < 1) return 'just now'
  if (diffMin < 60) return `${diffMin}m ago`
  const diffHr = Math.floor(diffMin / 60)
  if (diffHr < 24) return `${diffHr}h ago`
  return `${Math.floor(diffHr / 24)}d ago`
}

interface ActivityFeedProps {
  events?: ActivityEvent[]
  loading?: boolean
  studioId?: string
}

export function ActivityFeed({ events: initialEvents, loading, studioId }: ActivityFeedProps) {
  const [localEvents, setLocalEvents] = useState<ActivityEvent[]>(initialEvents ?? [])

  // Sync when parent passes new initial data
  useEffect(() => {
    setLocalEvents(initialEvents ?? [])
  }, [initialEvents])

  // Supabase Realtime subscription
  useEffect(() => {
    if (!studioId) return
    const supabase = createClient()
    const channel = supabase
      .channel(`activity-feed:${studioId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'activity_log',
          filter: `studio_id=eq.${studioId}`,
        },
        (payload) => {
          const raw = payload.new as ActivityLogRow
          setLocalEvents((prev) => [mapRowToEvent(raw), ...prev].slice(0, 20))
        },
      )
      .subscribe()

    return () => {
      void supabase.removeChannel(channel)
    }
  }, [studioId])

  if (loading) {
    return (
      <div className="rounded-xl border border-border/50 bg-card p-5 shadow-[var(--shadow-card)]">
        <div className="mb-4 flex items-center justify-between">
          <Skeleton className="h-5 w-36" />
          <Skeleton className="h-4 w-16" />
        </div>
        <div className="flex flex-col gap-3">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="flex items-start gap-3 py-3 border-b border-border/40 last:border-0">
              <Skeleton className="mt-0.5 h-7 w-7 shrink-0 rounded-md" />
              <div className="flex-1 space-y-1.5">
                <Skeleton className="h-3 w-full" />
                <Skeleton className="h-3 w-3/4" />
              </div>
            </div>
          ))}
        </div>
      </div>
    )
  }

  return (
    <div className="rounded-xl border border-border/50 bg-card p-5 shadow-[var(--shadow-card)]">
      <div className="mb-1 flex items-center justify-between">
        <Typography variant="h2">Recent Activity</Typography>
        <Link
          href="/appointments"
          className="text-xs text-primary hover:underline underline-offset-2"
        >
          View all
        </Link>
      </div>

      {localEvents.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-10">
          <Activity className="mb-3 h-8 w-8 text-muted-foreground/40" aria-hidden="true" />
          <p className="text-sm text-muted-foreground">No recent activity</p>
        </div>
      ) : (
        <ul className="flex flex-col divide-y divide-border/40 max-h-[420px] overflow-y-auto overscroll-contain">
          {localEvents.slice(0, 20).map((event) => {
            const Icon = EVENT_ICONS[event.type] ?? EVENT_ICONS['booking_confirmed']
            const bgClass = EVENT_ICON_BG[event.type] ?? 'bg-primary/10 text-primary'
            return (
              <li
                key={event.id}
                className="flex items-start gap-3 py-3 motion-safe:animate-in motion-safe:fade-in-0 motion-safe:slide-in-from-top-1"
              >
                <div
                  className={cn(
                    'mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-md',
                    bgClass,
                  )}
                  aria-hidden="true"
                >
                  <Icon className="h-3.5 w-3.5" />
                </div>
                <div className="flex min-w-0 flex-1 items-start justify-between gap-2">
                  <div className="min-w-0">
                    <p className="text-sm font-medium leading-tight">{event.title}</p>
                    <p className="text-xs text-muted-foreground">{event.detail}</p>
                  </div>
                  <span className="shrink-0 text-xs text-muted-foreground/60">{event.timeAgo}</span>
                </div>
              </li>
            )
          })}
        </ul>
      )}
    </div>
  )
}
