export interface Alert {
  id: string
  severity: 'warning' | 'error'
  message: string
  detail?: string
  href?: string
  actionLabel?: string
}

interface AlertsCardProps {
  alerts?: Alert[]
  loading?: boolean
  onDismiss?: (id: string) => void
}

export function AlertsCard({ alerts, loading, onDismiss }: AlertsCardProps) {
  const [dismissingIds, setDismissingIds] = useState<string[]>([])

  function handleDismiss(id: string) {
    setDismissingIds((prev) => [...prev, id])
    // Allow CSS transition to complete before parent removes the item
    setTimeout(() => {
      onDismiss?.(id)
      setDismissingIds((prev) => prev.filter((d) => d !== id))
    }, 150)
  }

  if (loading) {
    return (
      <div className="rounded-xl border border-border/50 bg-card p-5 shadow-[var(--shadow-card)]">
        <div className="mb-4 flex items-center gap-2">
          <Skeleton className="h-5 w-16" />
          <Skeleton className="h-5 w-6 rounded-full" />
        </div>
        <div className="flex flex-col gap-3">
          <Skeleton className="h-14 w-full rounded-md" />
          <Skeleton className="h-14 w-full rounded-md" />
        </div>
      </div>
    )
  }

  const count = alerts?.length ?? 0

  return (
    <div className="rounded-xl border border-border/50 bg-card p-5 shadow-[var(--shadow-card)]">
      <div className="mb-4 flex items-center gap-2">
        <Typography variant="h2">Alerts</Typography>
        {count > 0 && (
          <Badge
            variant="secondary"
            className="h-5 min-w-5 justify-center rounded-full px-1.5 text-[11px] font-semibold"
          >
            {count}
          </Badge>
        )}
      </div>

      {count === 0 ? (
        <div className="flex flex-col items-center justify-center py-6">
          <CheckCircle2
            className="mb-2 h-8 w-8 text-emerald-500"
            aria-hidden="true"
          />
          <p className="text-sm font-medium text-center">All clear</p>
          <p className="text-xs text-muted-foreground text-center mt-0.5">
            No outstanding alerts
          </p>
        </div>
      ) : (
        <ul className="flex flex-col divide-y divide-border/40">
          {alerts!.map((alert) => (
            <li
              key={alert.id}
              className={cn(
                'group flex items-start gap-3 py-3 first:pt-0 last:pb-0 transition-opacity duration-150',
                dismissingIds.includes(alert.id) && 'opacity-0',
              )}
            >
              {alert.severity === 'warning' ? (
                <AlertTriangle
                  className="mt-0.5 h-4 w-4 shrink-0 text-amber-500"
                  aria-hidden="true"
                />
              ) : (
                <AlertCircle
                  className="mt-0.5 h-4 w-4 shrink-0 text-destructive"
                  aria-hidden="true"
                />
              )}
              <div className="min-w-0 flex-1">
                <p className="text-sm font-medium leading-snug">{alert.message}</p>
                {alert.detail && (
                  <p className="text-xs text-muted-foreground">{alert.detail}</p>
                )}
                {alert.href && alert.actionLabel && (
                  <Link
                    href={alert.href}
                    className="text-xs text-primary hover:underline underline-offset-2"
                  >
                    {alert.actionLabel}
                  </Link>
                )}
              </div>
              {onDismiss && (
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-5 w-5 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity"
                  aria-label={`Dismiss alert: ${alert.message}`}
                  onClick={() => handleDismiss(alert.id)}
                >
                  <X className="h-3 w-3" aria-hidden="true" />
                </Button>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}
