import { useEffect } from 'react'
import Link from 'next/link'
import { AlertTriangle } from 'lucide-react'
import { logger } from '@/lib/logger'
import { Button } from '@/components/ui/button'
import { Typography } from '@/components/ui/typography'

type PageErrorVariant = 'full-page' | 'inline' | 'customer'

interface PageErrorProps {
  error: Error & { digest?: string }
  reset: () => void
  routeContext?: string
  variant?: PageErrorVariant
}

export function PageError({ error, reset, routeContext, variant = 'full-page' }: PageErrorProps) {
  useEffect(() => {
    logger.error('PageError boundary triggered', {
      error: error.message,
      digest: error.digest,
      routeContext,
      variant,
    })
  }, [error, routeContext, variant])

  const isFullPage = variant === 'full-page'
  const isCustomer = variant === 'customer'
  const isInline = variant === 'inline'

  const body = isCustomer
    ? 'We hit a snag. Please try again — if this keeps happening, contact support.'
    : isInline
    ? 'Failed to load this section. Retry or refresh the page.'
    : 'An unexpected error occurred. Our team has been notified.'

  return (
    <div
      role="alert"
      className={[
        'flex flex-col items-center justify-center gap-4 p-8 text-center',
        isInline ? 'py-8' : 'min-h-[60vh]',
      ].join(' ')}
    >
      <div className="flex size-16 items-center justify-center rounded-2xl bg-destructive/8 mb-2">
        <AlertTriangle className="size-8 text-destructive/60" aria-hidden="true" />
      </div>

      <Typography variant={isInline ? 'h3' : 'h2'}>Something went wrong</Typography>

      <Typography variant="body" className="text-muted-foreground max-w-sm">
        {body}
      </Typography>

      {isFullPage && error.digest && (
        <Typography variant="caption" className="font-mono">
          Error ID: {error.digest}
        </Typography>
      )}

      <div className="flex flex-wrap items-center justify-center gap-3 mt-2">
        <Button onClick={reset}>Try again</Button>

        {isFullPage && (
          <Button variant="outline" render={<Link href="/dashboard" />}>
            Go to dashboard
          </Button>
        )}

        {isCustomer && (
          <>
            <Button variant="outline" render={<Link href="/" />}>
              Go home
            </Button>
            <Button variant="outline" render={<a href="mailto:support@inkos.io" />}>
              Contact support
            </Button>
          </>
        )}
      </div>
    </div>
  )
}
