'use client'

import { ChevronLeft, ChevronRight, CalendarDays, CalendarRange, Calendar, List, Plus, Printer, Download } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type CalendarView = 'timeGridDay' | 'timeGridWeek' | 'dayGridMonth' | 'listWeek'

interface CalendarToolbarProps {
  view: CalendarView
  title: string
  studioId?: string
  rangeStart?: string
  rangeEnd?: string
  onViewChange: (view: CalendarView) => void
  onPrev: () => void
  onNext: () => void
  onToday: () => void
  onNewAppointment: () => void
}

const VIEW_SEGMENTS: { value: CalendarView; label: string; icon: React.ReactNode }[] = [
  { value: 'timeGridDay', label: 'Day', icon: <CalendarDays className="h-3.5 w-3.5" aria-hidden="true" /> },
  { value: 'timeGridWeek', label: 'Week', icon: <CalendarRange className="h-3.5 w-3.5" aria-hidden="true" /> },
  { value: 'dayGridMonth', label: 'Month', icon: <Calendar className="h-3.5 w-3.5" aria-hidden="true" /> },
  { value: 'listWeek', label: 'Agenda', icon: <List className="h-3.5 w-3.5" aria-hidden="true" /> },
]

export function CalendarToolbar({
  view,
  title,
  studioId,
  rangeStart,
  rangeEnd,
  onViewChange,
  onPrev,
  onNext,
  onToday,
  onNewAppointment,
}: CalendarToolbarProps) {
  function handlePrint() {
    window.print()
  }

  function handleDownload() {
    const params = new URLSearchParams()
    if (studioId) params.set('studioId', studioId)
    if (rangeStart) params.set('start', rangeStart)
    if (rangeEnd) params.set('end', rangeEnd)
    const url = `/api/calendar/export?${params.toString()}`
    const a = document.createElement('a')
    a.href = url
    a.download = `inkos-calendar-${rangeStart ?? 'export'}.ics`
    a.click()
  }

  return (
    <div className="calendar-toolbar flex items-center justify-between gap-3 border-b border-border/40 bg-background px-4 h-14 sticky top-14 z-30">
      {/* Left: nav cluster + title */}
      <div className="flex items-center gap-3 min-w-0">
        <div className="flex items-center gap-1">
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8"
            onClick={onPrev}
            aria-label="Previous period"
          >
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <Button
            variant="outline"
            size="sm"
            className="h-8 text-xs"
            onClick={onToday}
          >
            Today
          </Button>
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8"
            onClick={onNext}
            aria-label="Next period"
          >
            <ChevronRight className="h-4 w-4" />
          </Button>
        </div>
        <span className="text-sm font-medium tabular-nums text-foreground truncate hidden sm:block">
          {title}
        </span>
      </div>

      {/* Right: view segment control + print/download + new */}
      <div className="flex items-center gap-2 shrink-0">
        {/* 4-segment toggle */}
        <div
          role="group"
          aria-label="Calendar view"
          className="inline-flex items-center rounded-md border border-border/60 bg-muted/40 p-0.5 gap-0.5"
        >
          {VIEW_SEGMENTS.map((seg) => (
            <button
              key={seg.value}
              type="button"
              role="button"
              aria-pressed={view === seg.value}
              onClick={() => onViewChange(seg.value)}
              className={cn(
                'inline-flex items-center gap-1.5 rounded px-2.5 h-7 text-xs font-medium transition-colors',
                view === seg.value
                  ? 'bg-background text-foreground shadow-[var(--shadow-soft)]'
                  : 'text-muted-foreground hover:text-foreground hover:bg-background/60',
              )}
            >
              {seg.icon}
              <span className="hidden sm:inline">{seg.label}</span>
            </button>
          ))}
        </div>

        {/* Print */}
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8 hidden sm:inline-flex"
          onClick={handlePrint}
          aria-label="Print calendar"
        >
          <Printer className="h-3.5 w-3.5" />
        </Button>

        {/* Download iCal */}
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8 hidden sm:inline-flex"
          onClick={handleDownload}
          aria-label="Download calendar (.ics)"
        >
          <Download className="h-3.5 w-3.5" />
        </Button>

        {/* New appointment */}
        <Button
          size="sm"
          className="h-8 text-xs gap-1.5"
          onClick={onNewAppointment}
        >
          <Plus className="h-3.5 w-3.5" />
          <span className="hidden sm:inline">New</span>
        </Button>
      </div>
    </div>
  )
}
'use client'

import { Users2, Circle, Layers } from 'lucide-react'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { Checkbox } from '@/components/ui/checkbox'
import { Label } from '@/components/ui/label'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

const STATUSES: { value: BookingStatus; label: string }[] = [
  { value: 'pending', label: 'Pending' },
  { value: 'confirmed', label: 'Confirmed' },
  { value: 'in_progress', label: 'In Progress' },
  { value: 'completed', label: 'Completed' },
  { value: 'cancelled', label: 'Cancelled' },
  { value: 'no_show', label: 'No Show' },
]

const STATUS_DOT_CLASSES: Record<BookingStatus, string> = {
  pending: 'bg-[var(--color-status-pending)]',
  confirmed: 'bg-[var(--color-status-confirmed)]',
  in_progress: 'bg-[var(--color-status-in-progress)]',
  completed: 'bg-[var(--color-status-completed)]',
  cancelled: 'bg-[var(--color-status-cancelled)]',
  no_show: 'bg-[var(--color-status-no-show)]',
}

interface Artist {
  id: string
  display_name: string
  sort_order: number
  colorClass: string
}

interface Service {
  id: string
  name: string
}

interface CalendarFilterRowProps {
  artists: Artist[]
  services: Service[]
  filterArtistIds: string[]
  filterStatuses: string[]
  filterServiceIds: string[]
  onArtistFilterChange: (ids: string[]) => void
  onStatusFilterChange: (statuses: string[]) => void
  onServiceFilterChange: (ids: string[]) => void
}

export function CalendarFilterRow({
  artists,
  services,
  filterArtistIds,
  filterStatuses,
  filterServiceIds,
  onArtistFilterChange,
  onStatusFilterChange,
  onServiceFilterChange,
}: CalendarFilterRowProps) {
  const toggleArtist = (id: string) => {
    onArtistFilterChange(
      filterArtistIds.includes(id)
        ? filterArtistIds.filter((a) => a !== id)
        : [...filterArtistIds, id]
    )
  }

  const toggleStatus = (status: string) => {
    onStatusFilterChange(
      filterStatuses.includes(status)
        ? filterStatuses.filter((s) => s !== status)
        : [...filterStatuses, status]
    )
  }

  const toggleService = (id: string) => {
    onServiceFilterChange(
      filterServiceIds.includes(id)
        ? filterServiceIds.filter((s) => s !== id)
        : [...filterServiceIds, id]
    )
  }

  const artistLabel =
    filterArtistIds.length === 0
      ? 'All Artists'
      : filterArtistIds.length === 1
        ? artists.find((a) => a.id === filterArtistIds[0])?.display_name ?? '1 artist'
        : `${filterArtistIds.length} artists`

  const statusLabel =
    filterStatuses.length === 0 ? 'All Statuses' : `${filterStatuses.length} statuses`

  const serviceLabel =
    filterServiceIds.length === 0
      ? 'All Services'
      : filterServiceIds.length === 1
        ? services.find((s) => s.id === filterServiceIds[0])?.name ?? '1 service'
        : `${filterServiceIds.length} services`

  return (
    <div className="calendar-filter-row flex flex-wrap items-center gap-2 border-b border-border/30 px-4 py-2">
      {/* Artist filter */}
      <Popover>
        <PopoverTrigger
          className={cn(
            'inline-flex items-center gap-1.5 rounded-md px-3 h-8 text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-accent transition-colors',
            filterArtistIds.length > 0 && 'text-foreground bg-primary/10 border border-primary/20'
          )}
        >
          <Users2 className="h-3.5 w-3.5" />
          {artistLabel}
        </PopoverTrigger>
        <PopoverContent className="w-52 p-2" align="start">
          <div className="space-y-1">
            <button
              type="button"
              className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-sm hover:bg-accent"
              onClick={() => onArtistFilterChange([])}
            >
              <span className="text-xs text-muted-foreground">All Artists</span>
            </button>
            {artists.map((artist) => (
              <div
                key={artist.id}
                className="flex items-center gap-2 rounded-md px-2 py-1.5 hover:bg-accent cursor-pointer"
                onClick={() => toggleArtist(artist.id)}
              >
                <Checkbox
                  id={`artist-${artist.id}`}
                  checked={filterArtistIds.includes(artist.id)}
                  onCheckedChange={() => toggleArtist(artist.id)}
                />
                <span className={cn('h-2.5 w-2.5 rounded-full shrink-0', artist.colorClass)} />
                <Label htmlFor={`artist-${artist.id}`} className="text-xs cursor-pointer flex-1">
                  {artist.display_name}
                </Label>
              </div>
            ))}
          </div>
        </PopoverContent>
      </Popover>

      {/* Status filter */}
      <Popover>
        <PopoverTrigger
          className={cn(
            'inline-flex items-center gap-1.5 rounded-md px-3 h-8 text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-accent transition-colors',
            filterStatuses.length > 0 && 'text-foreground bg-primary/10 border border-primary/20'
          )}
        >
          <Circle className="h-3.5 w-3.5" />
          {statusLabel}
        </PopoverTrigger>
        <PopoverContent className="w-48 p-2" align="start">
          <div className="space-y-1">
            {STATUSES.map(({ value, label }) => (
              <div
                key={value}
                className="flex items-center gap-2 rounded-md px-2 py-1.5 hover:bg-accent cursor-pointer"
                onClick={() => toggleStatus(value)}
              >
                <Checkbox
                  id={`status-${value}`}
                  checked={filterStatuses.includes(value)}
                  onCheckedChange={() => toggleStatus(value)}
                />
                <span className={cn('h-2 w-2 rounded-full shrink-0', STATUS_DOT_CLASSES[value])} />
                <Label htmlFor={`status-${value}`} className="text-xs cursor-pointer flex-1">
                  {label}
                </Label>
              </div>
            ))}
          </div>
        </PopoverContent>
      </Popover>

      {/* Service filter — only shown when services available */}
      {services.length > 0 && (
        <Popover>
          <PopoverTrigger
            className={cn(
              'inline-flex items-center gap-1.5 rounded-md px-3 h-8 text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-accent transition-colors',
              filterServiceIds.length > 0 && 'text-foreground bg-primary/10 border border-primary/20'
            )}
          >
            <Layers className="h-3.5 w-3.5" />
            {serviceLabel}
          </PopoverTrigger>
          <PopoverContent className="w-52 p-2" align="start">
            <div className="space-y-1">
              <button
                type="button"
                className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-sm hover:bg-accent"
                onClick={() => onServiceFilterChange([])}
              >
                <span className="text-xs text-muted-foreground">All Services</span>
              </button>
              {services.map((service) => (
                <div
                  key={service.id}
                  className="flex items-center gap-2 rounded-md px-2 py-1.5 hover:bg-accent cursor-pointer"
                  onClick={() => toggleService(service.id)}
                >
                  <Checkbox
                    id={`service-${service.id}`}
                    checked={filterServiceIds.includes(service.id)}
                    onCheckedChange={() => toggleService(service.id)}
                  />
                  <Label htmlFor={`service-${service.id}`} className="text-xs cursor-pointer flex-1">
                    {service.name}
                  </Label>
                </div>
              ))}
            </div>
          </PopoverContent>
        </Popover>
      )}
    </div>
  )
}

'use client'

import dynamic from 'next/dynamic'
import { useCallback } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { Skeleton } from '@/components/ui/skeleton'
import { AppointmentDrawer } from '@/components/appointments/AppointmentDrawer'
import type { CalendarBooking } from '@/components/calendar/CalendarView'
import { useCalendarDrawer } from '@/hooks/calendar/use-calendar-drawer'

// Must be ssr:false — FullCalendar uses browser globals
const CalendarView = dynamic(
  () =>
    import('@/components/calendar/CalendarView').then((mod) => mod.CalendarView),
  {
    ssr: false,
    loading: () => (
      <div className="flex-1 p-4 space-y-3">
        <div className="flex items-center gap-3">
          <Skeleton className="h-9 w-32 rounded-lg" />
          <Skeleton className="h-9 w-24 rounded-lg" />
          <Skeleton className="h-9 w-24 rounded-lg" />
          <div className="ml-auto flex gap-2">
            <Skeleton className="h-9 w-9 rounded-lg" />
            <Skeleton className="h-9 w-20 rounded-lg" />
            <Skeleton className="h-9 w-9 rounded-lg" />
          </div>
        </div>
        <Skeleton className="h-[60vh] w-full rounded-xl" />
      </div>
    ),
  }
)

// ── C7: URL search param helpers ────────────────────────────────────────────
function parseIds(value: string | null): string[] {
  if (!value) return []
  return value.split(',').filter(Boolean)
}

function serializeIds(ids: string[]): string {
  return ids.join(',')
}

export function CalendarPageClient() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const queryClient = useQueryClient()

  // ── C7: Lift filter state into URL ─────────────────────────────────────
  const filterArtistIds = parseIds(searchParams.get('artists'))
  const filterStatuses = parseIds(searchParams.get('statuses'))
  const filterServiceIds = parseIds(searchParams.get('services'))

  function updateFilters(updates: {
    artists?: string[]
    statuses?: string[]
    services?: string[]
  }) {
    const next = new URLSearchParams(searchParams.toString())
    if (updates.artists !== undefined) {
      if (updates.artists.length > 0) {
        next.set('artists', serializeIds(updates.artists))
      } else {
        next.delete('artists')
      }
    }
    if (updates.statuses !== undefined) {
      if (updates.statuses.length > 0) {
        next.set('statuses', serializeIds(updates.statuses))
      } else {
        next.delete('statuses')
      }
    }
    if (updates.services !== undefined) {
      if (updates.services.length > 0) {
        next.set('services', serializeIds(updates.services))
      } else {
        next.delete('services')
      }
    }
    router.replace(`?${next.toString()}`, { scroll: false })
  }

  // ── Drawer state ────────────────────────────────────────────────────────
  const {
    drawerOpen,
    setDrawerOpen,
    editingId,
    defaultStart,
    defaultEnd,
    openNew,
    openEdit,
  } = useCalendarDrawer()

  const {
    data,
    isLoading,
    error,
    refetch,
  } = useQuery<{ data: CalendarBooking[]; count: number }>({
    queryKey: ['bookings', 'calendar'],
    queryFn: async () => {
      const res = await fetch('/api/bookings?per_page=500')
      if (!res.ok) throw new Error('Failed to fetch bookings')
      return res.json() as Promise<{ data: CalendarBooking[]; count: number }>
    },
  })

  const rescheduleMutation = useMutation({
    mutationFn: async ({
      id,
      newStart,
      newEnd,
    }: {
      id: string
      newStart: Date
      newEnd: Date
    }) => {
      const durationMs = newEnd.getTime() - newStart.getTime()
      const duration_min = Math.round(durationMs / 60000)
      const res = await fetch(`/api/bookings/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          scheduled_at: newStart.toISOString(),
          duration_min,
        }),
      })
      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Reschedule failed')
      }
      return res.json()
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
    },
  })

  const handleReschedule = useCallback(
    async (id: string, newStart: Date, newEnd: Date) => {
      await rescheduleMutation.mutateAsync({ id, newStart, newEnd })
    },
    [rescheduleMutation]
  )

  const bookings = data?.data ?? []
  const totalBookings = data?.count ?? 0

  return (
    <div className="flex flex-col flex-1 overflow-hidden h-full">
      <CalendarView
        bookings={bookings}
        isLoading={isLoading}
        error={error ? (error instanceof Error ? error.message : 'Unknown error') : null}
        totalBookings={totalBookings}
        filterArtistIds={filterArtistIds}
        filterStatuses={filterStatuses}
        filterServiceIds={filterServiceIds}
        onArtistFilterChange={(ids) => updateFilters({ artists: ids })}
        onStatusFilterChange={(statuses) => updateFilters({ statuses })}
        onServiceFilterChange={(ids) => updateFilters({ services: ids })}
        onNewAppointment={openNew}
        onEditAppointment={openEdit}
        onReschedule={handleReschedule}
        onRetry={() => {
          void refetch()
        }}
      />

      <AppointmentDrawer
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        editingId={editingId}
        {...(defaultStart !== undefined ? { defaultStart } : {})}
        {...(defaultEnd !== undefined ? { defaultEnd } : {})}
        onSuccess={() => {
          setDrawerOpen(false)
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
          toast.success(editingId ? 'Appointment updated' : 'Appointment created')
        }}
      />
    </div>
  )
}

