'use client'

import { useState, useEffect } from 'react'

interface LoadingTimeoutResult {
  showConnectionHint: boolean
  showSlowHint: boolean
}

export function useLoadingTimeout(isLoading: boolean): LoadingTimeoutResult {
  const [showConnectionHint, setShowConnectionHint] = useState(false)
  const [showSlowHint, setShowSlowHint] = useState(false)

  useEffect(() => {
    if (!isLoading) {
      setShowConnectionHint(false)
      setShowSlowHint(false)
      return
    }

    const t1 = setTimeout(() => setShowConnectionHint(true), 3000)
    const t2 = setTimeout(() => setShowSlowHint(true), 10000)

    return () => {
      clearTimeout(t1)
      clearTimeout(t2)
    }
  }, [isLoading])

  return { showConnectionHint, showSlowHint }

